/// The map `[..; H]` of `[..; W]` of `[T; C]` stored at the start of `s` (NHWC).
fn view<T, const H: usize, const W: usize, const C: usize>(s: &[T]) -> &[[[T; C]; W]; H] {
    let (pixels, _) = s.as_chunks::<C>();
    let (rows, _) = pixels.as_chunks::<W>();
    rows.first_chunk::<H>()
        .expect("the arena plan gives every map its size")
}

/// [`view`], writable.
fn view_mut<T, const H: usize, const W: usize, const C: usize>(
    s: &mut [T],
) -> &mut [[[T; C]; W]; H] {
    let (pixels, _) = s.as_chunks_mut::<C>();
    let (rows, _) = pixels.as_chunks_mut::<W>();
    rows.first_chunk_mut::<H>()
        .expect("the arena plan gives every map its size")
}

/// The vector `[T; N]` stored at the start of `s`.
fn view1<T, const N: usize>(s: &[T]) -> &[T; N] {
    s.first_chunk::<N>()
        .expect("the arena plan gives every vector its size")
}

/// [`view1`], writable.
fn view1_mut<T, const N: usize>(s: &mut [T]) -> &mut [T; N] {
    s.first_chunk_mut::<N>()
        .expect("the arena plan gives every vector its size")
}

/// Run the network on an input in the `INPUT` grid, with every intermediate
/// activation in `arena` (its contents need not be kept between calls).
pub fn forward(input: &Input, arena: &mut Arena) -> Output {
    {
        let (_, rest) = arena.split_at_mut(0);
        let (y, _) = rest.split_at_mut(512);
        CONV0.forward(input, view_mut::<_, 8, 8, 8>(y));
    }
    {
        let (lo, rest) = arena.split_at_mut(512);
        let (y, _) = rest.split_at_mut(512);
        CONV1.forward(view::<_, 8, 8, 8>(&lo[0..512]), view_mut::<_, 8, 8, 8>(y));
    }
    {
        let (_, rest) = arena.split_at_mut(0);
        let (y, hi) = rest.split_at_mut(512);
        ADD2.forward_in_place(view_mut::<_, 8, 8, 8>(y), view::<_, 8, 8, 8>(&hi[0..512]));
    }
    {
        let (lo, rest) = arena.split_at_mut(512);
        let (y, _) = rest.split_at_mut(128);
        MAXPOOL3.forward(view::<_, 8, 8, 8>(&lo[0..512]), view_mut::<_, 4, 4, 8>(y));
    }
    {
        let (_, rest) = arena.split_at_mut(256);
        let (y, hi) = rest.split_at_mut(128);
        DW4.forward(view::<_, 4, 4, 8>(&hi[128..256]), view_mut::<_, 4, 4, 8>(y));
    }
    {
        let (_, rest) = arena.split_at_mut(0);
        let (y, hi) = rest.split_at_mut(256);
        PW5.forward(view::<_, 4, 4, 8>(&hi[0..128]), view_mut::<_, 4, 4, 16>(y));
    }
    FC6.forward(view1::<_, 256>(&arena[0..256]))
}
